@Composable private fun CartPane(cart:MutableList<Pair<JSONObject,Int>>,note:String,setNote:(String)->Unit,submit:()->Unit,busy:Boolean,modifier:Modifier){Card(modifier){Column(Modifier.padding(12.dp)){Text("購物車",fontSize=20.sp,fontWeight=FontWeight.Bold);LazyColumn(Modifier.weight(1f,false)){itemsIndexed(cart){index,line->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(line.first.text("name"));Text(money(line.first.int("price_minor")*line.second))};TextButton({if(line.second==1)cart.removeAt(index)else cart[index]=line.first to line.second-1}){Text("−")};Text("${line.second}");TextButton({cart[index]=line.first to (line.second+1).coerceAtMost(20)}){Text("＋")}}}};OutlinedTextField(note,setNote,label={Text("訂單備註")},modifier=Modifier.fillMaxWidth());Text("總計 ${money(cart.sumOf{it.first.int("price_minor")*it.second})}",fontSize=22.sp,fontWeight=FontWeight.Black);Button(submit,enabled=cart.isNotEmpty()&&!busy,modifier=Modifier.fillMaxWidth().heightIn(min=48.dp)){Text(if(busy)"送單中…" else "送單")}}}}

private fun submitPos(api:MerchantApi,cart:List<Pair<JSONObject,Int>>,type:String,table:String,note:String,scope:kotlinx.coroutines.CoroutineScope,setBusy:(Boolean)->Unit,done:(String)->Unit){setBusy(true);scope.launch{try{val body=JSONObject().put("order_type",type).put("table_label",table).put("customer_note",note).put("items",JSONArray(cart.map{JSONObject().put("item_id",it.first.text("id")).put("quantity",it.second).put("option_value_ids",JSONArray())}));val result=withContext(Dispatchers.IO){api.counterOrder(body,"counter-${UUID.randomUUID()}")};done(if(result.optBoolean("queued"))"目前離線，訂單待同步，尚未送達廚房。" else "櫃台訂單建立成功") }catch(e:Exception){done(e.message.orEmpty())}finally{setBusy(false)}}}

